pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 nestedAmount) public {
        vm.assume(amount > 0 && amount < 1e30);
        vm.assume(nestedAmount > 0 && nestedAmount < 1e30);
        ReentrantAttacker attacker = new ReentrantAttacker(c, nestedAmount);
        vm.deal(address(attacker), amount + nestedAmount);
        attacker.deposit(amount);
        assertTrue(c.getBalance(address(attacker)) == amount, "balance must equal single deposit");
    }
}

contract ReentrantAttacker {
    C c;
    uint256 nestedAmount;
    bool fired;
    constructor(C _c, uint256 _nestedAmount) { c = _c; nestedAmount = _nestedAmount; }
    function deposit(uint256 amount) external {
        c.addToBalance{value: amount}();
    }
    receive() external payable {
        if (!fired && nestedAmount <= address(this).balance) {
            fired = true;
            c.addToBalance{value: nestedAmount}();
        }
    }
}

