pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IC {
    function addToBalance() external payable;
    function withdrawBalance() external;
    function getBalance(address u) external view returns (uint256);
}

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(IC(address(c)));
    }

    function testFuzz_property(uint128 d1, uint128 d2) public {
        uint256 amt1 = bound(uint256(d1), 1, 1e18);
        uint256 amt2 = bound(uint256(d2), uint256(d1), 2e18); // ensure c can fund a second payout

        vm.deal(address(attacker), amt1);
        vm.prank(address(attacker));
        c.addToBalance{value: amt1}();

        address victim = address(0xBEEF);
        vm.deal(victim, amt2);
        vm.prank(victim);
        c.addToBalance{value: amt2}();

        // re-entrant double withdrawal attempt
        attacker.attack();

        // General rule: the contract's ETH balance always equals the sum of
        // all recorded user balances (no value can leave without the ledger
        // reflecting it). The bug lets the attacker withdraw twice, so the
        // contract's balance falls below the recorded sum.
        assertTrue(
            address(c).balance == c.getBalance(address(attacker)) + c.getBalance(victim),
            "contract ETH balance must equal sum of recorded user balances"
        );
    }
}

contract Attacker {
    IC public immutable c;
    uint256 public reentered;

    constructor(IC _c) {
        c = _c;
    }

    function attack() external {
        c.withdrawBalance();
    }

    receive() external payable {
        if (reentered == 0) {
            reentered = 1;
            try c.withdrawBalance() {
                // double withdrawal succeeded (buggy version)
            } catch {
                // correctly blocked by reentrancy guard
            }
        }
    }
}

