pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker att;

    function setUp() public {
        c = new C();
        att = new Attacker(c);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);

        // Fund and deposit through the attacker, then withdraw from it.
        vm.deal(address(att), amount);
        att.deposit{value: amount}();

        bool ok;
        try att.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: a withdrawal where the recipient re-enters addToBalance must
        // always revert (the lock is held for the whole guarded body). The
        // mutant releases the lock before the body, so the re-entrant nested
        // call succeeds and the withdrawal completes instead.
        assertTrue(!ok);
    }
}

contract Attacker {
    C c;

    constructor(C c_) {
        c = c_;
    }

    function deposit() external payable {
        c.addToBalance{value: msg.value}();
    }

    function withdraw() external {
        c.withdrawBalance();
    }

    receive() external payable {
        c.addToBalance();
    }
}

