pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker att;

    function setUp() public {
        c = new C();
        att = new Attacker(c);
    }

    function testFuzz_property(uint256 amount, uint256 redeposit) public {
        // admissible domain: positive deposit and positive re-entrant deposit amount
        amount = bound(amount, 1, 1e30);
        redeposit = bound(redeposit, 1, 1e30);

        vm.deal(address(att), amount + redeposit);

        // Attacker deposits `amount`, withdraws it; while receiving the payout ETH
        // it re-enters addToBalance with `redeposit`. In the reference, the
        // reentrancy lock is held, so that nested deposit reverts (swallowed by
        // the attacker) and the attacker's recorded balance is exactly 0 after
        // the withdrawal. In the buggy mutant the lock is released early, so the
        // nested deposit succeeds and the recorded balance becomes `redeposit != 0`.
        att.depositAndRedeposit(amount, redeposit);

        assertTrue(c.getBalance(address(att)) == 0);
    }
}

contract Attacker {
    C c;
    bool tried;
    uint256 redepositAmt;

    constructor(C c_) {
        c = c_;
    }

    function depositAndRedeposit(uint256 amount, uint256 redeposit) external {
        redepositAmt = redeposit;
        c.addToBalance{value: amount}();
        c.withdrawBalance();
    }

    receive() external payable {
        if (!tried) {
            tried = true;
            // re-enter during the payout; reverts under the reference's lock
            try c.addToBalance{value: redepositAmt}() {} catch {}
        }
    }
}

