pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 seed) public {
        amount = bound(amount, 1, 1e30);
        Attacker a = new Attacker();
        vm.deal(address(a), amount);
        bool outerOk = a.attack(c, amount, seed % 2 == 0);
        // The outer addToBalance always succeeds, but the re-entrant nested
        // addToBalance issued during its execution must revert because the
        // reentrancy lock is held for the whole guarded body.
        assertTrue(a.nestedOk() == false, "reentrant addToBalance must revert while guarded");
        outerOk; // outer call outcome noted; assertion above is the deciding fact
    }
}

contract Attacker {
    bool public nestedOk;

    function attack(C c, uint256 amount, bool nested) external returns (bool outerOk) {
        // nested == true: attempt the re-entrant deposit inside the outer call
        (bool ok, ) = address(c).call{value: amount}(
            abi.encodeWithSignature("addToBalance()")
        );
        outerOk = ok;
        if (nested && ok) nestedOk = true;
        // re-enter inside the outer call
        if (nested) {
            C target = c;
            target.reenterHook();
        }
    }
}

